This is a classic exercism food chain problem. Let's try implementing it algorithmically.

Verse structure:
- Verse 1 (fly): "I know an old lady who swallowed a fly." + "I don't know why she swallowed the fly. Perhaps she'll die."
- Verse 2 (spider): "I know an old lady who swallowed a spider." + "It wriggled and jiggled and tickled inside her." + "She swallowed the spider to catch the fly." + the fly's final line.
- Verse 3 (bird): first line + "How absurd to swallow a bird!" + "She swallowed the bird to catch the spider that wriggled and jiggled and tickled inside her." + "She swallowed the spider to catch the fly." + final line.
- ...
- Verse 8 (horse): "I know an old lady who swallowed a horse." + "She's dead, of course!"

In other words, animals: fly, spider, bird, cat, dog, goat, cow, horse.

Each verse: "I know an old lady who swallowed a {animal}."
Next, a comment line (except for fly and horse):
- fly: none (goes straight to the final line)
- spider: "It wriggled and jiggled and tickled inside her."
- bird: "How absurd to swallow a bird!"
- cat: "Imagine that, to swallow a cat!"
- dog: "What a hog, to swallow a dog!"
- goat: "Just opened her throat and swallowed a goat!"
- cow: "I don't know how she swallowed a cow!"
- horse: "She's dead, of course!"

Next, the chain: for animals after fly, "She swallowed the {prev} to catch the {next}." — but for the spider, "She swallowed the bird to catch the spider that wriggled and jiggled and tickled inside her." — the spider gets the "that wriggled..." suffix.

The final line (for all except horse): "I don't know why she swallowed the fly. Perhaps she'll die."

Let's write the implementation:

```go
package foodchain

import "strings"

var animals = []string{"", "fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

var comments = map[int]string{
	2: "It wriggled and jiggled and tickled inside her.",
	3: "How absurd to swallow a bird!",
	4: "Imagine that, to swallow a cat!",
	5: "What a hog, to swallow a dog!",
	6: "Just opened her throat and swallowed a goat!",
	7: "I don't know how she swallowed a cow!",
	8: "She's dead, of course!",
}

func Verse(v int) string {
	var b strings.Builder
	b.WriteString("I know an old lady who swallowed a " + animals[v] + ".\n")
	if c, ok := comments[v]; ok {
		b.WriteString(c + "\n")
	}
	if v == 8 {
		return b.String()
	}
	for i := v; i >= 2; i-- {
		catch := animals[i-1]
		if i-1 == 2 {
			catch += " that wriggled and jiggled and tickled inside her"
		}
		b.WriteString("She swallowed the " + animals[i] + " to catch the " + catch + ".\n")
	}
	b.WriteString("I don't know why she swallowed the fly. Perhaps she'll die.")
	return b.String()
}

func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, 8)
}
