package foodchain

import "strings"

// animals is indexed by verse number: animals[v] is the creature of verse v.
var animals = []string{"", "fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

// comments holds the second line of each verse, where one exists.
// Verse 1 (fly) has no comment; verse 8 (horse) ends with it.
var comments = map[int]string{
	2: "It wriggled and jiggled and tickled inside her.",
	3: "How absurd to swallow a bird!",
	4: "Imagine that, to swallow a cat!",
	5: "What a hog, to swallow a dog!",
	6: "Just opened her throat and swallowed a goat!",
	7: "I don't know how she swallowed a cow!",
	8: "She's dead, of course!",
}

const finalLine = "I don't know why she swallowed the fly. Perhaps she'll die."

func Verse(v int) string {
	var b strings.Builder
	b.WriteString("I know an old lady who swallowed a ")
	b.WriteString(animals[v])
	b.WriteString(".\n")
	if c, ok := comments[v]; ok {
		b.WriteString(c)
		b.WriteByte('\n')
	}
	if v == 8 {
		return b.String()
	}
	// The cumulative chain: each animal was swallowed to catch the previous one.
	for i := v; i >= 2; i-- {
		b.WriteString("She swallowed the ")
		b.WriteString(animals[i])
		b.WriteString(" to catch the ")
		b.WriteString(animals[i-1])
		if i-1 == 2 {
			b.WriteString(" that wriggled and jiggled and tickled inside her")
		}
		b.WriteString(".\n")
	}
	b.WriteString(finalLine)
	return b.String()
}

func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, 8)
}

